#!/bin/sh
# 分离编译：编译单元独立编译后再链接
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > add.c << 'EOF'
int add(int a, int b)
{
    return a + b;
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int add(int, int);

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

gcc -c add.c -o add.o      # 只编译：产生目标文件，add 尚可未解析
gcc -c main.c -o main.o    # 只编译：main.o 里 add 是未定义符号
nm main.o                  # 注意 U add：欠账
gcc main.o add.o -o app    # 链接：把 U add 补上
./app
